"""Contoh kalimat & penggunaan — de_11 (ungkapan kerja, Ausbildung, Pflege & birokrasi)."""

EXAMPLES = [
    # (kata, kalimat, bacaan, terjemahan_id, terjemahan_en, pakai_id, pakai_en)
    # --- Salam & sopan santun kerja ---
    ("Mahlzeit!", "Mahlzeit! Gehst du auch in die Kantine?", "",
     "Selamat makan siang! Kamu juga ke kantin?", "Enjoy your lunch! Are you going to the canteen too?",
     "Netral. Salam khas kantor/pabrik sekitar jam makan siang, ke Chef maupun kolega. Bukan 'Guten Appetit' saat makan, tapi sapaan lewat di lorong.",
     "Neutral. Typical office/factory greeting around lunchtime, to boss or colleagues. Not just 'enjoy your meal' at the table, but a hallway greeting."),
    ("Schönen Feierabend!", "Tschüss, Anna, schönen Feierabend!", "",
     "Dah, Anna, selamat istirahat sepulang kerja!", "Bye, Anna, have a nice evening!",
     "Netral. Salam perpisahan saat pulang kerja, untuk du maupun Sie. Feierabend = waktu setelah jam kerja, bukan 'malam pesta'.",
     "Neutral. Farewell when leaving work, fine with du or Sie. Feierabend = time after work, not a 'party evening'."),
    ("Darf ich Sie duzen?", "Wir arbeiten ja jeden Tag zusammen. Darf ich Sie duzen?", "",
     "Kita kan kerja bareng tiap hari. Boleh saya pakai 'du' dengan Anda?", "We work together every day. May I call you 'du'?",
     "Sopan/formal (Sie). Biasanya yang lebih tua atau atasan yang menawarkan du duluan; sebagai pegawai baru lebih aman menunggu ditawari.",
     "Polite/formal (Sie). Usually the older person or the boss offers du first; as a new employee it's safer to wait to be offered."),
    ("Wir können uns gerne duzen", "Ich bin Jonas. Wir können uns gerne duzen.", "",
     "Saya Jonas. Kita pakai 'du' saja.", "I'm Jonas. Let's use 'du' with each other.",
     "Netral. Tawaran beralih dari Sie ke du. Kalau ditawari, jawab saja: Gerne, ich bin ... Di banyak tim muda du sudah biasa sejak hari pertama.",
     "Neutral. Offer to switch from Sie to du. If offered, just answer: Gerne, ich bin ... In many young teams du is normal from day one."),
    ("Ich bin neu hier", "Hallo, ich bin neu hier. Ich heiße Siti.", "",
     "Halo, saya baru di sini. Nama saya Siti.", "Hi, I'm new here. My name is Siti.",
     "Netral. Untuk memperkenalkan diri di hari pertama ke kolega. Membuat orang lebih maklum kalau Anda bertanya banyak.",
     "Neutral. To introduce yourself to colleagues on your first day. Makes people more patient with your many questions."),
    ("Herzlich willkommen im Team!", "Herzlich willkommen im Team! Schön, dass du da bist.", "",
     "Selamat bergabung di tim! Senang kamu ada di sini.", "Welcome to the team! Great to have you here.",
     "Netral. Ucapan Chef/kolega untuk pegawai baru. Balasan wajar: Danke, ich freue mich!",
     "Neutral. What the boss/colleagues say to a new hire. Natural reply: Danke, ich freue mich!"),
    ("Ich freue mich auf die Zusammenarbeit", "Vielen Dank für die Zusage. Ich freue mich auf die Zusammenarbeit!", "",
     "Terima kasih atas penerimaannya. Saya menantikan kerja sama ini!", "Thank you for the acceptance. I look forward to working together!",
     "Sopan/netral. Cocok di akhir wawancara, email ke Chef, atau hari pertama. Perhatikan: sich freuen auf = menantikan (yang akan datang).",
     "Polite/neutral. Good at the end of an interview, in an email to the boss, or on day one. Note: sich freuen auf = look forward to (future)."),
    ("Guten Morgen zusammen!", "Guten Morgen zusammen! Wer möchte Kaffee?", "",
     "Selamat pagi semuanya! Siapa mau kopi?", "Good morning, everyone! Who wants coffee?",
     "Netral. Sapaan ke satu ruangan/tim sekaligus. Zusammen di sini berarti 'semuanya', bukan 'bersama-sama'.",
     "Neutral. Greeting a whole room/team at once. Zusammen here means 'everyone', not 'together'."),
    ("Entschuldigen Sie die Störung", "Entschuldigen Sie die Störung, Frau Weber. Haben Sie einen Moment?", "",
     "Maaf mengganggu, Bu Weber. Anda ada waktu sebentar?", "Sorry to disturb you, Ms Weber. Do you have a moment?",
     "Sopan/formal (Sie). Saat masuk ke ruangan Chef atau menyela orang yang sedang bekerja. Versi du: Entschuldige die Störung.",
     "Polite/formal (Sie). When entering the boss's office or interrupting someone working. du version: Entschuldige die Störung."),
    ("Haben Sie kurz Zeit?", "Herr Schmidt, haben Sie kurz Zeit? Ich habe eine Frage zum Dienstplan.", "",
     "Pak Schmidt, Anda ada waktu sebentar? Saya ada pertanyaan soal jadwal kerja.", "Mr Schmidt, do you have a moment? I have a question about the rota.",
     "Sopan/formal (Sie). Untuk Chef atau Pflegedienstleitung. Ke kolega: Hast du kurz Zeit? Kurz = sebentar saja, membuat permintaan terdengar ringan.",
     "Polite/formal (Sie). For the boss or nursing manager. To a colleague: Hast du kurz Zeit? Kurz = briefly, making the request sound light."),
    ("Vielen Dank für die Einarbeitung", "Vielen Dank für die Einarbeitung, ich habe sehr viel gelernt.", "",
     "Terima kasih sudah membimbing saya, saya belajar banyak sekali.", "Thanks for showing me the ropes, I learned a lot.",
     "Netral. Einarbeitung = masa pengenalan/pelatihan kerja oleh kolega senior. Ucapkan di akhir minggu-minggu pertama, ke mentor atau Chef.",
     "Neutral. Einarbeitung = induction/on-the-job training by a senior colleague. Say it after the first weeks, to your mentor or boss."),
    ("Kein Problem, mache ich gern", "Kannst du die Post holen? - Kein Problem, mache ich gern.", "",
     "Bisa ambil suratnya? - Tidak masalah, dengan senang hati.", "Can you fetch the mail? - No problem, happy to do it.",
     "Netral. Jawaban ramah saat dimintai tolong. Bentuk lisan tanpa subjek di depan (mache ich = das mache ich) sangat umum.",
     "Neutral. Friendly reply when asked for a favour. Dropping das at the start (mache ich = das mache ich) is very common in speech."),
    ("Ich mache jetzt Pause", "Ich mache jetzt Pause. In dreißig Minuten bin ich zurück.", "",
     "Saya istirahat dulu sekarang. Tiga puluh menit lagi saya kembali.", "I'm taking my break now. I'll be back in thirty minutes.",
     "Netral. Pause machen = istirahat kerja; di Jerman jam istirahat diatur hukum, jadi wajar mengumumkannya. Jangan pakai 'Ich nehme Pause'.",
     "Neutral. Pause machen = take a break; breaks are regulated by law in Germany, so announcing it is normal. Don't say 'Ich nehme Pause'."),
    ("Ich mache jetzt Feierabend", "Es ist schon fünf. Ich mache jetzt Feierabend.", "",
     "Sudah jam lima. Saya pulang kerja sekarang.", "It's already five. I'm calling it a day.",
     "Netral. Artinya selesai kerja hari ini. Feierabend machen, bukan 'Feierabend gehen'.",
     "Neutral. Means finishing work for the day. Feierabend machen, not 'Feierabend gehen'."),
    ("Wie war dein Wochenende?", "Hallo Tom! Wie war dein Wochenende?", "",
     "Halo Tom! Bagaimana akhir pekanmu?", "Hi Tom! How was your weekend?",
     "Santai (du). Basa-basi khas Senin pagi ke kolega. Versi Sie: Wie war Ihr Wochenende?",
     "Casual (du). Typical Monday-morning small talk with colleagues. Sie version: Wie war Ihr Wochenende?"),
    # --- Instruksi, laporan & pertanyaan ---
    ("Ich bin fertig", "Ich bin fertig mit Zimmer zwölf. Was kommt jetzt?", "",
     "Kamar dua belas sudah selesai. Sekarang apa lagi?", "I'm done with room twelve. What's next?",
     "Netral. Laporan bahwa tugas selesai, ke Chef atau kolega. Hati-hati: dengan nada lelah juga bisa berarti 'aku capek banget'.",
     "Neutral. Reporting a finished task to boss or colleague. Careful: in a tired tone it can also mean 'I'm exhausted'."),
    ("Können Sie das bitte wiederholen?", "Entschuldigung, können Sie das bitte wiederholen?", "",
     "Maaf, bisa tolong diulangi?", "Sorry, could you repeat that, please?",
     "Sopan/formal (Sie). Jauh lebih baik bertanya daripada pura-pura paham. Ke kolega: Kannst du das bitte wiederholen?",
     "Polite/formal (Sie). Much better to ask than to pretend you understood. To a colleague: Kannst du das bitte wiederholen?"),
    ("Können Sie bitte langsamer sprechen?", "Mein Deutsch ist noch nicht so gut. Können Sie bitte langsamer sprechen?", "",
     "Bahasa Jerman saya belum begitu bagus. Bisa tolong bicara lebih pelan?", "My German isn't very good yet. Could you speak more slowly, please?",
     "Sopan/formal (Sie). Berguna di Behörde, telepon, atau dengan Chef. Langsamer = lebih pelan (bentuk komparatif).",
     "Polite/formal (Sie). Useful at offices, on the phone or with the boss. Langsamer = more slowly (comparative)."),
    ("Was soll ich als Nächstes machen?", "Die Betten sind gemacht. Was soll ich als Nächstes machen?", "",
     "Tempat tidurnya sudah dirapikan. Apa yang harus saya kerjakan selanjutnya?", "The beds are made. What should I do next?",
     "Netral. Menunjukkan inisiatif setelah tugas selesai. Nächstes ditulis kapital karena dipakai sebagai kata benda.",
     "Neutral. Shows initiative after finishing a task. Nächstes is capitalised because it's used as a noun."),
    ("Wie meinen Sie das?", "Ich soll das anders machen? Wie meinen Sie das?", "",
     "Saya harus mengerjakannya dengan cara lain? Maksud Anda bagaimana?", "I should do it differently? What do you mean by that?",
     "Sopan/formal (Sie). Minta penjelasan, nada harus netral agar tidak terdengar menantang. Versi du: Wie meinst du das?",
     "Polite/formal (Sie). Asking for clarification; keep the tone neutral so it doesn't sound confrontational. du version: Wie meinst du das?"),
    ("Habe ich das richtig verstanden?", "Ich soll also zuerst die Wäsche machen. Habe ich das richtig verstanden?", "",
     "Jadi saya harus mengurus cucian dulu. Apakah saya paham dengan benar?", "So I should do the laundry first. Did I understand that correctly?",
     "Netral. Ulangi instruksi dengan kata-kata sendiri lalu tanyakan ini. Sangat dihargai di Pflege karena mencegah kesalahan.",
     "Neutral. Repeat the instruction in your own words, then ask this. Much appreciated in nursing because it prevents mistakes."),
    ("Können Sie mir das zeigen?", "Ich kenne dieses Gerät noch nicht. Können Sie mir das zeigen?", "",
     "Saya belum kenal alat ini. Bisa tunjukkan caranya ke saya?", "I don't know this device yet. Can you show me how?",
     "Sopan/formal (Sie). Untuk minta diperagakan, bukan cuma dijelaskan. Ke kolega: Kannst du mir das zeigen?",
     "Polite/formal (Sie). Asking for a demonstration, not just an explanation. To a colleague: Kannst du mir das zeigen?"),
    ("Darf ich kurz etwas fragen?", "Darf ich kurz etwas fragen? Wo sind die Handschuhe?", "",
     "Boleh saya bertanya sebentar? Sarung tangannya di mana?", "May I ask something quickly? Where are the gloves?",
     "Netral, sopan. Pembuka pertanyaan yang aman untuk siapa saja, du maupun Sie.",
     "Neutral, polite. A safe way to open a question with anyone, du or Sie."),
    ("Das habe ich noch nie gemacht", "Einen Katheter legen? Das habe ich noch nie gemacht.", "",
     "Memasang kateter? Saya belum pernah melakukannya.", "Insert a catheter? I've never done that before.",
     "Netral. Jujur soal batas kemampuan itu penting, terutama di Pflege. Lanjutkan dengan: Können Sie es mir zeigen?",
     "Neutral. Being honest about your limits is important, especially in nursing. Follow up with: Können Sie es mir zeigen?"),
    ("Das mache ich sofort", "Der Patient in Zimmer drei braucht Wasser. - Das mache ich sofort.", "",
     "Pasien di kamar tiga butuh air. - Akan segera saya kerjakan.", "The patient in room three needs water. - I'll do it right away.",
     "Netral. Jawaban sigap atas permintaan Chef/kolega. Sofort = segera, sekarang juga.",
     "Neutral. Prompt reply to a request from boss/colleague. Sofort = immediately."),
    ("Bis wann soll das fertig sein?", "Den Bericht schreibe ich. Bis wann soll das fertig sein?", "",
     "Laporannya saya yang tulis. Ini harus selesai kapan?", "I'll write the report. When does it need to be done?",
     "Netral. Tanyakan tenggat agar tidak salah paham. Orang Jerman menghargai kejelasan waktu (Pünktlichkeit).",
     "Neutral. Ask for the deadline to avoid misunderstandings. Germans value clear timing (Pünktlichkeit)."),
    ("Ich habe einen Fehler gemacht", "Es tut mir leid, ich habe einen Fehler gemacht. Ich korrigiere das.", "",
     "Maaf, saya membuat kesalahan. Saya perbaiki.", "I'm sorry, I made a mistake. I'll fix it.",
     "Netral. Mengakui kesalahan langsung dianggap profesional, bukan memalukan. Fehler machen, bukan 'Fehler tun'.",
     "Neutral. Admitting a mistake directly is seen as professional, not embarrassing. Fehler machen, not 'Fehler tun'."),
    ("Es kommt nicht wieder vor", "Entschuldigung für die Verspätung. Es kommt nicht wieder vor.", "",
     "Maaf atas keterlambatannya. Tidak akan terulang lagi.", "Sorry for being late. It won't happen again.",
     "Netral. Janji setelah minta maaf ke Chef. Vorkommen = terjadi; vor ada di akhir kalimat.",
     "Neutral. A promise after apologising to the boss. Vorkommen = to happen; vor goes to the end."),
    ("Ich kümmere mich darum", "Der Drucker funktioniert nicht? Ich kümmere mich darum.", "",
     "Printernya tidak jalan? Biar saya yang urus.", "The printer isn't working? I'll take care of it.",
     "Netral. Mengambil alih tanggung jawab. Sich kümmern um + Akkusativ; darum = um das.",
     "Neutral. Taking on responsibility. Sich kümmern um + accusative; darum = um das."),
    ("Wer ist dafür zuständig?", "Die Lieferung ist falsch. Wer ist dafür zuständig?", "",
     "Kirimannya salah. Siapa yang bertanggung jawab untuk ini?", "The delivery is wrong. Who is responsible for this?",
     "Netral. Kata kunci di kantor dan Behörde: zuständig = berwenang/bertugas menangani. Bukan untuk menyalahkan orang.",
     "Neutral. Key word at work and offices: zuständig = in charge of handling it. Not about blaming someone."),
    ("Ich gebe Ihnen Bescheid", "Ich frage meinen Chef. Ich gebe Ihnen Bescheid.", "",
     "Saya tanya atasan saya dan nanti saya kabari Anda.", "I'll ask my boss and let you know.",
     "Sopan/formal (Sie). Ke kolega: Ich gebe dir Bescheid / Ich sag dir Bescheid. Bescheid geben = memberi kabar.",
     "Polite/formal (Sie). To a colleague: Ich gebe dir Bescheid / Ich sag dir Bescheid. Bescheid geben = to let someone know."),
    ("Ich arbeite noch daran", "Ist die Präsentation fertig? - Nein, ich arbeite noch daran.", "",
     "Presentasinya sudah selesai? - Belum, masih saya kerjakan.", "Is the presentation finished? - No, I'm still working on it.",
     "Netral. Laporan progres. Arbeiten an + Dativ; daran = an der Sache.",
     "Neutral. Progress update. Arbeiten an + dative; daran = on it."),
    ("Alles erledigt", "Die Bestellung ist raus, die Mails sind beantwortet. Alles erledigt!", "",
     "Pesanan sudah dikirim, email sudah dibalas. Semua sudah beres!", "The order is out, the emails are answered. All taken care of!",
     "Netral. Laporan singkat bahwa semua tugas sudah selesai. Erledigen = menyelesaikan urusan.",
     "Neutral. Short report that all tasks are done. Erledigen = to get something done."),
    # --- Lamaran & Ausbildung ---
    ("Ich möchte mich um die Stelle bewerben", "Guten Tag, ich möchte mich um die Stelle bewerben, die Sie online ausgeschrieben haben.", "",
     "Selamat siang, saya ingin melamar posisi yang Anda iklankan secara online.", "Hello, I'd like to apply for the position you advertised online.",
     "Sopan/formal (Sie). Untuk telepon atau email lamaran. Sich bewerben um/für eine Stelle; untuk Ausbildung: sich um einen Ausbildungsplatz bewerben.",
     "Polite/formal (Sie). For calls or application emails. Sich bewerben um/für eine Stelle; for training: sich um einen Ausbildungsplatz bewerben."),
    ("Ich habe ein Vorstellungsgespräch", "Ich habe ein Vorstellungsgespräch im Krankenhaus, morgen um neun.", "",
     "Saya ada wawancara kerja di rumah sakit, besok jam sembilan.", "I have a job interview at the hospital, tomorrow at nine.",
     "Netral. Vorstellungsgespräch = wawancara kerja (bukan 'Interview' saja). Datanglah tepat waktu, bahkan 10 menit lebih awal.",
     "Neutral. Vorstellungsgespräch = job interview. Be on time, even ten minutes early."),
    ("Ich habe eine Zusage bekommen", "Gute Nachrichten: Ich habe eine Zusage bekommen!", "",
     "Kabar baik: lamaran saya diterima!", "Good news: I've been accepted!",
     "Netral. Zusage = jawaban 'ya' (diterima); lawannya Absage = penolakan.",
     "Neutral. Zusage = a yes (acceptance); the opposite is Absage = rejection."),
    ("Ich mache eine Ausbildung zur Pflegefachkraft", "Ich mache eine Ausbildung zur Pflegefachkraft in Stuttgart.", "",
     "Saya sedang Ausbildung jadi perawat di Stuttgart.", "I'm training to be a nurse in Stuttgart.",
     "Netral. Pola: eine Ausbildung zum/zur + profesi. Gelar resminya kini Pflegefachfrau/Pflegefachmann; Pflegefachkraft netral gender.",
     "Neutral. Pattern: eine Ausbildung zum/zur + job. The official title is now Pflegefachfrau/Pflegefachmann; Pflegefachkraft is gender-neutral."),
    ("Ich bin im ersten Lehrjahr", "Ich bin im ersten Lehrjahr und lerne noch viel.", "",
     "Saya di tahun pertama Ausbildung dan masih banyak belajar.", "I'm in my first year of training and still learning a lot.",
     "Netral. Lehrjahr = tahun Ausbildung (Azubi). Gaji Ausbildung biasanya naik tiap Lehrjahr.",
     "Neutral. Lehrjahr = year of apprenticeship. Training pay usually rises each year."),
    ("Ich bin in der Probezeit", "Ich bin in der Probezeit, deshalb kann ich keinen Urlaub nehmen.", "",
     "Saya masih dalam masa percobaan, jadi belum bisa ambil cuti.", "I'm on probation, so I can't take leave.",
     "Netral. Probezeit = masa percobaan (sering 6 bulan); selama itu kontrak bisa diputus lebih cepat.",
     "Neutral. Probezeit = probation period (often six months); the contract can be ended at short notice during it."),
    ("Wann ist mein erster Arbeitstag?", "Vielen Dank! Wann ist mein erster Arbeitstag?", "",
     "Terima kasih! Kapan hari pertama saya bekerja?", "Thank you! When is my first day at work?",
     "Netral. Ditanyakan setelah mendapat Zusage. Bisa juga tanyakan: Um wie viel Uhr soll ich da sein?",
     "Neutral. Ask after getting the acceptance. You can also ask: Um wie viel Uhr soll ich da sein?"),
    ("Wie viele Stunden arbeite ich pro Woche?", "Eine Frage zum Vertrag: Wie viele Stunden arbeite ich pro Woche?", "",
     "Satu pertanyaan soal kontrak: berapa jam kerja saya per minggu?", "A question about the contract: how many hours a week do I work?",
     "Sopan/netral. Wajar ditanyakan di wawancara atau saat tanda tangan kontrak. Vollzeit sekitar 38–40 jam, Teilzeit lebih sedikit.",
     "Polite/neutral. Normal to ask at the interview or contract signing. Full-time is about 38–40 hours, part-time less."),
    ("Morgen habe ich Berufsschule", "Morgen habe ich Berufsschule, ich bin erst am Donnerstag wieder im Betrieb.", "",
     "Besok saya masuk sekolah kejuruan, baru Kamis saya kembali ke tempat kerja.", "Tomorrow I have vocational school; I'm back at work on Thursday.",
     "Netral. Ausbildung ganda: sebagian hari di Berufsschule (teori), sebagian di Betrieb (praktik). Tanpa artikel: Berufsschule haben.",
     "Neutral. Dual training: some days at Berufsschule (theory), others at the company (practice). No article: Berufsschule haben."),
    # --- Perawatan (Pflege) ---
    ("Wie fühlen Sie sich heute?", "Guten Morgen, Frau Bauer! Wie fühlen Sie sich heute?", "",
     "Selamat pagi, Bu Bauer! Bagaimana perasaan Anda hari ini?", "Good morning, Mrs Bauer! How are you feeling today?",
     "Sopan/formal (Sie). Sapaan standar ke pasien/penghuni panti. Selalu Sie dan nama belakang kecuali pasien minta du.",
     "Polite/formal (Sie). Standard greeting for patients/residents. Always Sie and surname unless the patient asks for du."),
    ("Haben Sie Schmerzen?", "Haben Sie Schmerzen? Zeigen Sie mir bitte, wo.", "",
     "Apakah Anda merasa sakit? Tolong tunjukkan di mana.", "Are you in pain? Please show me where.",
     "Sopan/formal (Sie). Schmerzen biasanya jamak. Lanjutkan dengan skala: Wie stark, von eins bis zehn?",
     "Polite/formal (Sie). Schmerzen is usually plural. Follow with a scale: Wie stark, von eins bis zehn?"),
    ("Sagen Sie mir, wenn es wehtut", "Ich bewege jetzt Ihr Bein. Sagen Sie mir, wenn es wehtut.", "",
     "Saya gerakkan kaki Anda sekarang. Bilang ke saya kalau terasa sakit.", "I'm moving your leg now. Tell me if it hurts.",
     "Sopan/formal (Sie). Dipakai saat mobilisasi atau perawatan luka. Wehtun = terasa sakit (es tut weh).",
     "Polite/formal (Sie). Used during mobilisation or wound care. Wehtun = to hurt (es tut weh)."),
    ("Haben Sie gut geschlafen?", "Guten Morgen, Herr Klein. Haben Sie gut geschlafen?", "",
     "Selamat pagi, Pak Klein. Anda tidur nyenyak?", "Good morning, Mr Klein. Did you sleep well?",
     "Sopan/formal (Sie). Pertanyaan pagi yang ramah dan sekaligus info untuk dokumentasi. Versi du: Hast du gut geschlafen?",
     "Polite/formal (Sie). A friendly morning question that also gives info for documentation. du version: Hast du gut geschlafen?"),
    ("Ich helfe Ihnen beim Aufstehen", "Bleiben Sie bitte sitzen, ich helfe Ihnen beim Aufstehen.", "",
     "Tolong tetap duduk, saya bantu Anda berdiri.", "Please stay seated, I'll help you get up.",
     "Sopan/formal (Sie). Selalu umumkan tindakan sebelum menyentuh pasien. Beim + kata kerja jadi kata benda (Aufstehen, Anziehen, Essen).",
     "Polite/formal (Sie). Always announce an action before touching a patient. Beim + verb as noun (Aufstehen, Anziehen, Essen)."),
    ("Ich messe jetzt Ihren Blutdruck", "Bitte machen Sie den Arm frei, ich messe jetzt Ihren Blutdruck.", "",
     "Tolong singsingkan lengan baju, saya ukur tekanan darah Anda sekarang.", "Please roll up your sleeve, I'm going to take your blood pressure now.",
     "Sopan/formal (Sie). Blutdruck messen = mengukur tekanan darah. Ihren (bukan Ihre) karena der Blutdruck, Akkusativ.",
     "Polite/formal (Sie). Blutdruck messen = take blood pressure. Ihren (not Ihre) because der Blutdruck, accusative."),
    ("Ich messe jetzt Fieber", "Sie sind sehr warm. Ich messe jetzt Fieber.", "",
     "Badan Anda hangat sekali. Saya ukur suhu badan Anda sekarang.", "You feel very warm. I'm taking your temperature now.",
     "Netral. Fieber messen = mengukur suhu badan (walau belum tentu demam). Jangan diterjemahkan 'saya mengukur demam'.",
     "Neutral. Fieber messen = take someone's temperature (even if there's no fever). Not literally 'measure fever'."),
    ("Möchten Sie etwas trinken?", "Es ist heiß heute. Möchten Sie etwas trinken?", "",
     "Hari ini panas. Anda mau minum sesuatu?", "It's hot today. Would you like something to drink?",
     "Sopan/formal (Sie). Penting di panti lansia karena lansia sering kurang minum. Möchten lebih sopan daripada wollen.",
     "Polite/formal (Sie). Important in elderly care since older people often drink too little. Möchten is politer than wollen."),
    ("Bitte drehen Sie sich auf die Seite", "Ich wechsle jetzt das Bettlaken. Bitte drehen Sie sich auf die Seite.", "",
     "Saya ganti seprainya sekarang. Tolong miring ke samping.", "I'm changing the sheet now. Please turn onto your side.",
     "Sopan/formal (Sie). Instruksi saat ganti seprai atau cegah dekubitus. Lebih spesifik: auf die linke/rechte Seite.",
     "Polite/formal (Sie). Instruction when changing sheets or preventing pressure sores. More specific: auf die linke/rechte Seite."),
    ("Ich wasche Sie jetzt", "Das Wasser ist warm. Ich wasche Sie jetzt, ist das in Ordnung?", "",
     "Airnya hangat. Saya basuh Anda sekarang, tidak apa-apa?", "The water is warm. I'm going to wash you now, is that okay?",
     "Sopan/formal (Sie). Perawatan tubuh (Grundpflege) itu intim: umumkan dan minta persetujuan. Sie di sini objek (Anda), bukan subjek.",
     "Polite/formal (Sie). Personal care is intimate: announce it and ask for consent. Sie here is the object (you), not the subject."),
    ("Haben Sie Ihre Tabletten genommen?", "Haben Sie Ihre Tabletten genommen? Die weiße ist für das Herz.", "",
     "Anda sudah minum tabletnya? Yang putih untuk jantung.", "Have you taken your pills? The white one is for the heart.",
     "Sopan/formal (Sie). Dalam bahasa Jerman obat 'diambil' (nehmen), bukan 'diminum'. Jangan bilang 'Tabletten trinken'.",
     "Polite/formal (Sie). In German you 'take' (nehmen) medicine; don't say 'Tabletten trinken'."),
    ("Ich bringe Ihnen Ihre Medikamente", "Guten Abend, ich bringe Ihnen Ihre Medikamente für die Nacht.", "",
     "Selamat malam, saya bawakan obat Anda untuk malam ini.", "Good evening, I'm bringing you your medication for the night.",
     "Sopan/formal (Sie). Medikamente = obat-obatan (jamak). Ihnen = kepada Anda (Dativ), Ihre = milik Anda.",
     "Polite/formal (Sie). Medikamente = medication (plural). Ihnen = to you (dative), Ihre = your."),
    ("Ist Ihnen schwindelig?", "Sie sind so blass. Ist Ihnen schwindelig?", "",
     "Anda pucat sekali. Anda merasa pusing?", "You look so pale. Do you feel dizzy?",
     "Sopan/formal (Sie). Struktur Dativ: mir/Ihnen ist schwindelig (bukan 'Sie sind schwindelig'). Tanyakan sebelum pasien berdiri.",
     "Polite/formal (Sie). Dative structure: mir/Ihnen ist schwindelig (not 'Sie sind schwindelig'). Ask before the patient stands up."),
    ("Vorsicht, langsam!", "Vorsicht, langsam! Der Boden ist nass.", "",
     "Hati-hati, pelan-pelan! Lantainya basah.", "Careful, slowly! The floor is wet.",
     "Netral. Peringatan singkat untuk pasien maupun kolega. Vorsicht saja juga bisa berarti 'awas!'.",
     "Neutral. Short warning to patients or colleagues. Vorsicht alone can also mean 'watch out!'."),
    ("Bitte klingeln Sie, wenn Sie etwas brauchen", "Die Klingel ist hier. Bitte klingeln Sie, wenn Sie etwas brauchen.", "",
     "Belnya di sini. Tekan bel kalau butuh sesuatu.", "The call button is here. Please ring if you need anything.",
     "Sopan/formal (Sie). Diucapkan saat meninggalkan kamar pasien. Klingel = bel panggil di samping tempat tidur.",
     "Polite/formal (Sie). Said when leaving a patient's room. Klingel = the call button by the bed."),
    ("Ich wechsle jetzt den Verband", "Die Wunde sieht gut aus. Ich wechsle jetzt den Verband.", "",
     "Lukanya terlihat baik. Saya ganti perbannya sekarang.", "The wound looks good. I'm changing the dressing now.",
     "Netral. Verband wechseln = ganti perban. Wechsle (bukan wechsele) adalah bentuk lisan yang umum.",
     "Neutral. Verband wechseln = change the dressing. Wechsle is the common spoken form of wechsele."),
    ("Ich sage dem Arzt Bescheid", "Ihr Blutdruck ist sehr hoch. Ich sage dem Arzt Bescheid.", "",
     "Tekanan darah Anda tinggi sekali. Saya beri tahu dokter.", "Your blood pressure is very high. I'll tell the doctor.",
     "Netral. Ke pasien atau kolega. Jika dokternya perempuan: der Ärztin. Bescheid sagen = memberi tahu.",
     "Neutral. To a patient or colleague. If the doctor is a woman: der Ärztin. Bescheid sagen = to inform."),
    ("Ich mache jetzt die Übergabe", "Es ist kurz vor zwei. Ich mache jetzt die Übergabe an den Spätdienst.", "",
     "Sudah hampir jam dua. Saya serah terima ke shift sore sekarang.", "It's almost two. I'm doing the handover to the late shift now.",
     "Netral. Übergabe = serah terima informasi pasien antar-shift, sangat penting di Pflege. Ke tim: an den Spätdienst/Nachtdienst.",
     "Neutral. Übergabe = handover of patient information between shifts, crucial in nursing. To a team: an den Spätdienst/Nachtdienst."),
    ("Ich habe heute Frühdienst", "Ich habe heute Frühdienst und muss um sechs anfangen.", "",
     "Hari ini saya shift pagi dan harus mulai jam enam.", "I'm on the early shift today and have to start at six.",
     "Netral. Shift di Pflege: Frühdienst (pagi), Spätdienst (sore), Nachtdienst (malam). Juga disebut Frühschicht di pabrik.",
     "Neutral. Nursing shifts: Frühdienst (early), Spätdienst (late), Nachtdienst (night). Factories say Frühschicht."),
    ("Diese Woche habe ich Nachtdienst", "Diese Woche habe ich Nachtdienst, deshalb schlafe ich tagsüber.", "",
     "Minggu ini saya shift malam, jadi saya tidur siang hari.", "I'm on night shift this week, so I sleep during the day.",
     "Netral. Info ke kolega/teman soal jadwal. Diese Woche di depan membuat kata kerja (habe) di posisi kedua sebelum subjek.",
     "Neutral. Telling colleagues/friends your schedule. With diese Woche first, the verb (habe) comes second, before the subject."),
    # --- Sakit, izin & masalah ---
    ("Ich melde mich krank", "Guten Morgen, hier ist Rina. Ich melde mich krank, ich habe Fieber.", "",
     "Selamat pagi, ini Rina. Saya izin sakit, saya demam.", "Good morning, it's Rina. I'm calling in sick, I have a fever.",
     "Netral. Telepon ke Chef/kantor sebelum jam kerja mulai. Di Jerman lapor sakit harus segera, biasanya hari pertama.",
     "Neutral. Call your boss/office before work starts. In Germany you must report sickness immediately, usually on day one."),
    ("Ich bin krankgeschrieben", "Ich bin krankgeschrieben, bis einschließlich Freitag.", "",
     "Saya cuti sakit dengan surat dokter, sampai Jumat.", "I'm signed off sick, up to and including Friday.",
     "Netral. Artinya dokter sudah mengeluarkan surat sakit resmi (AU). Bedakan dengan sekadar krank (sakit).",
     "Neutral. Means a doctor has issued an official sick note (AU). Different from just krank (ill)."),
    ("Ich brauche eine Krankmeldung", "Ich brauche eine Krankmeldung für meinen Arbeitgeber.", "",
     "Saya butuh surat keterangan sakit untuk pemberi kerja saya.", "I need a sick note for my employer.",
     "Sopan/netral, ke dokter atau resepsionis praktik. Nama resminya Arbeitsunfähigkeitsbescheinigung (AU); kini sering dikirim digital (eAU).",
     "Polite/neutral, to the doctor or practice receptionist. Official name: Arbeitsunfähigkeitsbescheinigung (AU); now often sent digitally (eAU)."),
    ("Ich kann heute nicht zur Arbeit kommen", "Es tut mir leid, ich kann heute nicht zur Arbeit kommen. Mein Kind ist krank.", "",
     "Maaf, hari ini saya tidak bisa masuk kerja. Anak saya sakit.", "I'm sorry, I can't come to work today. My child is ill.",
     "Netral. Selalu sebut alasannya singkat. Zur Arbeit kommen/gehen = pergi kerja (bukan 'zu Arbeit').",
     "Neutral. Always give a brief reason. Zur Arbeit kommen/gehen = go to work (not 'zu Arbeit')."),
    ("Ich habe einen Arzttermin", "Ich habe einen Arzttermin um acht, ich komme danach.", "",
     "Saya ada janji dengan dokter jam delapan, setelah itu saya datang.", "I have a doctor's appointment at eight; I'll come afterwards.",
     "Netral. Beri tahu Chef sebelumnya. Termin = janji temu, bukan 'termin pembayaran'.",
     "Neutral. Tell your boss in advance. Termin = appointment, not a payment instalment."),
    ("Ich komme etwas später", "Ich komme etwas später, mein Bus ist nicht gekommen.", "",
     "Saya datang agak terlambat, bus saya tidak datang.", "I'll be a bit late, my bus didn't come.",
     "Netral. Kabari sebelum jam mulai, lewat telepon atau pesan. Orang Jerman sangat menghargai kabar keterlambatan.",
     "Neutral. Let people know before start time, by phone or message. Germans really value being told about delays."),
    ("Ich stehe im Stau", "Ich stehe im Stau auf der A8, ich bin in zwanzig Minuten da.", "",
     "Saya terjebak macet di A8, dua puluh menit lagi saya sampai.", "I'm stuck in traffic on the A8, I'll be there in twenty minutes.",
     "Netral. Im Stau stehen = terjebak macet (harfiah: berdiri di macet). Jangan 'Ich bin in Stau'.",
     "Neutral. Im Stau stehen = be stuck in traffic (literally 'stand in a jam'). Not 'Ich bin in Stau'."),
    ("Mein Zug hat Verspätung", "Mein Zug hat Verspätung, ich bin erst um halb neun da.", "",
     "Kereta saya terlambat, saya baru sampai jam setengah sembilan.", "My train is delayed, I won't be there until half past eight.",
     "Netral. Verspätung haben = terlambat (untuk kendaraan). Untuk orang: Ich bin zu spät / Ich verspäte mich.",
     "Neutral. Verspätung haben = be delayed (vehicles). For people: Ich bin zu spät / Ich verspäte mich."),
    ("Ich möchte Urlaub beantragen", "Ich möchte Urlaub beantragen, vom ersten bis zum fünfzehnten August.", "",
     "Saya ingin mengajukan cuti dari tanggal satu sampai lima belas Agustus.", "I'd like to request leave from the first to the fifteenth of August.",
     "Sopan/netral, ke Chef atau HR. Urlaub = cuti/liburan; biasanya diajukan jauh hari lewat formulir (Urlaubsantrag).",
     "Polite/neutral, to the boss or HR. Urlaub = leave/holiday; usually requested well in advance via a form (Urlaubsantrag)."),
    ("Kann ich heute früher gehen?", "Kann ich heute früher gehen? Ich habe um vier einen Termin beim Amt.", "",
     "Boleh hari ini saya pulang lebih awal? Saya ada janji di kantor pemerintah jam empat.", "Can I leave early today? I have an appointment at the authorities at four.",
     "Netral. Ke Chef; versi lebih sopan: Könnte ich heute früher gehen? Sertakan alasan.",
     "Neutral. To the boss; politer version: Könnte ich heute früher gehen? Give a reason."),
    ("Kann ich die Schicht tauschen?", "Am Samstag habe ich einen Termin. Kann ich die Schicht tauschen?", "",
     "Hari Sabtu saya ada urusan. Boleh saya tukar shift?", "I have an appointment on Saturday. Can I swap shifts?",
     "Netral. Ke atasan yang membuat Dienstplan. Ke kolega langsung: Können wir die Schicht tauschen?",
     "Neutral. To the person who makes the rota. To a colleague directly: Können wir die Schicht tauschen?"),
    ("Ich habe Überstunden gemacht", "Diesen Monat war viel los. Ich habe Überstunden gemacht, insgesamt zehn.", "",
     "Bulan ini sibuk sekali. Saya sudah lembur, total sepuluh jam.", "It was really busy this month. I've worked overtime, ten hours in total.",
     "Netral. Überstunden = jam lembur; bisa dibayar atau diganti libur (abbauen). Catat selalu jam lembur Anda.",
     "Neutral. Überstunden = overtime hours; paid or taken as time off (abbauen). Always record your overtime."),
    ("Ich hatte einen Arbeitsunfall", "Ich hatte einen Arbeitsunfall und habe mir die Hand verletzt.", "",
     "Saya mengalami kecelakaan kerja dan tangan saya terluka.", "I had an accident at work and hurt my hand.",
     "Netral. Laporkan segera ke Chef; kecelakaan kerja ditanggung asuransi khusus (Berufsgenossenschaft). Termasuk perjalanan ke kantor.",
     "Neutral. Report it to your boss immediately; work accidents are covered by special insurance (Berufsgenossenschaft), including the commute."),
    ("Das Gerät ist kaputt", "Das Gerät ist kaputt, es zeigt keine Werte mehr an.", "",
     "Alatnya rusak, tidak menampilkan angka lagi.", "The device is broken, it doesn't show any readings anymore.",
     "Netral. Laporan kerusakan ke kolega atau teknisi. Kaputt santai tapi dipakai di mana saja; formal: defekt.",
     "Neutral. Reporting a fault to colleagues or technicians. Kaputt is casual but used everywhere; formal: defekt."),
    ("Ich habe meinen Lohn noch nicht bekommen", "Entschuldigung, ich habe meinen Lohn noch nicht bekommen. Es geht um Oktober.", "",
     "Permisi, gaji saya belum masuk. Ini untuk bulan Oktober.", "Excuse me, I haven't received my wages yet. It's for October.",
     "Sopan/netral, ke HR (Personalabteilung) atau Chef. Lohn = upah/gaji; Gehalt = gaji bulanan pegawai kantor.",
     "Polite/neutral, to HR (Personalabteilung) or the boss. Lohn = wages; Gehalt = monthly salary of office staff."),
    ("Ich möchte kündigen", "Ich möchte kündigen. Wie lange ist meine Kündigungsfrist?", "",
     "Saya ingin mengundurkan diri. Berapa lama masa pemberitahuannya?", "I'd like to resign. How long is my notice period?",
     "Sopan/netral, ke Chef. Pengunduran diri harus tertulis dan ditandatangani; perhatikan Kündigungsfrist. Kündigen juga dipakai untuk putus kontrak sewa.",
     "Polite/neutral, to the boss. A resignation must be in writing and signed; check the notice period. Kündigen also means cancelling a lease."),
    # --- Kantor & birokrasi ---
    ("Ich möchte einen Termin vereinbaren", "Guten Tag, ich möchte einen Termin vereinbaren.", "",
     "Selamat siang, saya ingin membuat janji temu.", "Hello, I'd like to make an appointment.",
     "Sopan/formal (Sie). Hampir semua Behörde dan dokter di Jerman butuh Termin; sering lewat online. Sinonim: einen Termin machen.",
     "Polite/formal (Sie). Almost every office and doctor in Germany needs an appointment, often booked online. Synonym: einen Termin machen."),
    ("Ich habe um zehn Uhr einen Termin", "Guten Morgen, ich habe um zehn Uhr einen Termin bei Frau Lang.", "",
     "Selamat pagi, saya ada janji jam sepuluh dengan Bu Lang.", "Good morning, I have an appointment at ten with Ms Lang.",
     "Sopan/netral. Kalimat pertama di resepsionis. Sebut nama petugas jika tahu: bei Frau/Herrn ...",
     "Polite/neutral. First sentence at reception. Name the official if you know: bei Frau/Herrn ..."),
    ("Wo bekomme ich eine Wartenummer?", "Entschuldigung, wo bekomme ich eine Wartenummer?", "",
     "Permisi, di mana saya ambil nomor antrean?", "Excuse me, where do I get a queue number?",
     "Sopan/netral. Di Bürgeramt/Ausländerbehörde biasanya ada mesin nomor; tunggu sampai nomor Anda muncul di layar.",
     "Polite/neutral. At citizens' or immigration offices there's usually a ticket machine; wait until your number shows on the screen."),
    ("Ich möchte mich anmelden", "Ich bin neu in München. Ich möchte mich anmelden.", "",
     "Saya baru di München dan ingin mendaftarkan alamat.", "I'm new in Munich and would like to register my address.",
     "Sopan/netral, di Bürgeramt. Anmeldung wajib dalam 14 hari setelah pindah; bawa paspor dan Wohnungsgeberbestätigung. Di konteks lain juga berarti 'mendaftar' (kursus).",
     "Polite/neutral, at the citizens' office. Registration is required within 14 days of moving; bring your passport and landlord's confirmation. Elsewhere it also means signing up (e.g. a course)."),
    ("Ich möchte mich ummelden", "Ich bin umgezogen. Ich möchte mich ummelden.", "",
     "Saya sudah pindah rumah dan ingin melapor pindah alamat.", "I've moved and would like to register my change of address.",
     "Sopan/netral, di Bürgeramt. Ummelden = pindah alamat dalam Jerman; abmelden = lapor keluar (misalnya pulang ke Indonesia).",
     "Polite/neutral, at the citizens' office. Ummelden = change address within Germany; abmelden = deregister (e.g. moving back to Indonesia)."),
    ("Welche Unterlagen brauche ich?", "Ich möchte ein Visum beantragen. Welche Unterlagen brauche ich?", "",
     "Saya ingin mengajukan visa. Dokumen apa saja yang saya perlukan?", "I'd like to apply for a visa. Which documents do I need?",
     "Sopan/netral. Unterlagen = dokumen/berkas (selalu jamak). Tanyakan sebelum Termin agar tidak bolak-balik.",
     "Polite/neutral. Unterlagen = documents/paperwork (always plural). Ask before your appointment to avoid repeat visits."),
    ("Können Sie mir beim Ausfüllen helfen?", "Ich verstehe dieses Formular nicht. Können Sie mir beim Ausfüllen helfen?", "",
     "Saya tidak paham formulir ini. Bisa bantu saya mengisinya?", "I don't understand this form. Can you help me fill it in?",
     "Sopan/formal (Sie). Ausfüllen = mengisi (formulir). Di banyak kota ada layanan bantuan migran gratis untuk ini.",
     "Polite/formal (Sie). Ausfüllen = fill in (a form). Many cities offer free migrant advice services for this."),
    ("Wo muss ich unterschreiben?", "Ich habe alles gelesen. Wo muss ich unterschreiben?", "",
     "Saya sudah membaca semuanya. Di mana saya harus tanda tangan?", "I've read everything. Where do I need to sign?",
     "Sopan/netral. Jangan tanda tangan sebelum paham isinya, terutama kontrak kerja/sewa. Unterschrift = tanda tangan.",
     "Polite/neutral. Don't sign before you understand the content, especially job or rental contracts. Unterschrift = signature."),
    ("Bis wann muss ich das abgeben?", "Das Formular nehme ich mit. Bis wann muss ich das abgeben?", "",
     "Formulirnya saya bawa pulang. Batas waktu penyerahannya kapan?", "I'll take the form with me. By when do I have to hand it in?",
     "Sopan/netral. Tenggat (Frist) di Behörde ketat; terlambat bisa berarti permohonan ditolak. Abgeben = menyerahkan.",
     "Polite/neutral. Deadlines (Frist) at offices are strict; being late can mean rejection. Abgeben = to hand in."),
    ("Ich brauche eine Kopie davon", "Das ist mein Arbeitsvertrag. Ich brauche eine Kopie davon.", "",
     "Ini kontrak kerja saya. Saya perlu salinannya.", "This is my employment contract. I need a copy of it.",
     "Netral. Simpan salinan semua dokumen penting. Beglaubigte Kopie = salinan yang dilegalisir.",
     "Neutral. Keep copies of all important documents. Beglaubigte Kopie = certified copy."),
    ("Muss ich das übersetzen lassen?", "Mein Zeugnis ist auf Indonesisch. Muss ich das übersetzen lassen?", "",
     "Ijazah saya berbahasa Indonesia. Apakah ini harus diterjemahkan?", "My certificate is in Indonesian. Do I need to have it translated?",
     "Sopan/netral. Übersetzen lassen = menyuruh orang lain menerjemahkan; dokumen resmi butuh penerjemah tersumpah (vereidigter Übersetzer).",
     "Polite/neutral. Übersetzen lassen = have someone translate it; official documents need a sworn translator (vereidigter Übersetzer)."),
    ("Wie lange dauert die Bearbeitung?", "Ich habe den Antrag abgegeben. Wie lange dauert die Bearbeitung?", "",
     "Permohonannya sudah saya serahkan. Berapa lama prosesnya?", "I've submitted the application. How long does processing take?",
     "Sopan/netral. Bearbeitung = pemrosesan berkas. Jawabannya sering dalam minggu atau bulan, jadi ajukan lebih awal.",
     "Polite/neutral. Bearbeitung = processing of a file. Answers are often in weeks or months, so apply early."),
    ("Ich habe einen Brief vom Amt bekommen", "Ich habe einen Brief vom Amt bekommen und verstehe ihn nicht.", "",
     "Saya dapat surat dari kantor pemerintah dan tidak memahaminya.", "I got a letter from the authorities and don't understand it.",
     "Netral. Amt = kantor pemerintah secara umum (Finanzamt, Jobcenter...). Surat resmi jangan diabaikan, sering ada tenggat.",
     "Neutral. Amt = a government office in general (tax office, job centre...). Never ignore official letters; they often have deadlines."),
    ("Können Sie mir diesen Brief erklären?", "Der Brief ist von der Krankenkasse. Können Sie mir diesen Brief erklären?", "",
     "Suratnya dari asuransi kesehatan. Bisa jelaskan surat ini ke saya?", "The letter is from the health insurance. Could you explain this letter to me?",
     "Sopan/formal (Sie). Ke petugas, konsultan, atau kolega Jerman yang Anda percaya. Versi du: Kannst du mir den Brief erklären?",
     "Polite/formal (Sie). To an official, adviser or trusted German colleague. du version: Kannst du mir den Brief erklären?"),
    ("Ich möchte meine Aufenthaltserlaubnis verlängern", "Guten Tag, ich möchte meine Aufenthaltserlaubnis verlängern.", "",
     "Selamat siang, saya ingin memperpanjang izin tinggal saya.", "Hello, I'd like to extend my residence permit.",
     "Sopan/formal (Sie), di Ausländerbehörde. Ajukan sebelum masa berlaku habis; bawa kontrak kerja dan bukti tempat tinggal.",
     "Polite/formal (Sie), at the immigration office. Apply before it expires; bring your job contract and proof of address."),
    ("Mein Visum läuft bald ab", "Mein Visum läuft bald ab. Was muss ich jetzt tun?", "",
     "Visa saya sebentar lagi habis. Apa yang harus saya lakukan sekarang?", "My visa expires soon. What do I have to do now?",
     "Netral. Ablaufen = habis masa berlaku; ab terpisah ke akhir kalimat. Sama untuk paspor: Mein Pass läuft ab.",
     "Neutral. Ablaufen = to expire; ab separates to the end. Same for passports: Mein Pass läuft ab."),
    ("Ich habe die Anerkennung beantragt", "Ich habe die Anerkennung beantragt, aber noch keine Antwort bekommen.", "",
     "Saya sudah mengajukan penyetaraan ijazah, tapi belum dapat jawaban.", "I've applied for recognition of my qualification but haven't had an answer yet.",
     "Netral. Anerkennung = pengakuan/penyetaraan ijazah luar negeri, wajib untuk perawat sebelum bekerja penuh sebagai Pflegefachkraft.",
     "Neutral. Anerkennung = recognition of a foreign qualification, required for nurses before working fully as a registered nurse."),
    ("Ich möchte ein Konto eröffnen", "Guten Tag, ich möchte ein Konto eröffnen. Ich bin neu in Deutschland.", "",
     "Selamat siang, saya ingin membuka rekening. Saya baru di Jerman.", "Hello, I'd like to open an account. I'm new in Germany.",
     "Sopan/formal (Sie), di bank. Gaji di Jerman dibayar ke rekening (Girokonto); biasanya perlu Anmeldung dulu.",
     "Polite/formal (Sie), at the bank. Wages in Germany are paid into a current account (Girokonto); you usually need address registration first."),
]
